
(function($){'use strict';if(!$||$.fn.select2)return;
var active=null;
function close(){if(active){active.remove();active=null;$(document).off('.novinfontSelect2');$(window).off('.novinfontSelect2');}}
function textOf($s){var $o=$s.find('option:selected');return $o.length?$o.text():'';}
function sync($s,$box){$box.find('.select2-selection__rendered').text(textOf($s));$box.toggleClass('select2-container--disabled',$s.prop('disabled'));}
function place($s,$box,$drop){var r=$box[0].getBoundingClientRect();$drop.css({position:'fixed',top:(r.bottom+6)+'px',left:r.left+'px',width:r.width+'px',zIndex:1000000});}
function open($s,$box,opts){if($s.prop('disabled'))return;close();var dir=(opts&&opts.dir)||'ltr';var $drop=$('<span class="select2-dropdown novinfont-select2-dropdown" dir="'+dir+'"><span class="select2-search select2-search--dropdown"><input class="select2-search__field" type="search" autocomplete="off" spellcheck="false"></span><span class="select2-results"><ul class="select2-results__options" role="listbox"></ul></span></span>');var $list=$drop.find('.select2-results__options'),$search=$drop.find('.select2-search__field');function render(term){term=(term||'').trim().toLowerCase();$list.empty();var c=0;$s.find('option').each(function(){var $o=$(this),label=$o.text(),val=$o.val();if($o.prop('disabled'))return;if(term&&label.toLowerCase().indexOf(term)===-1)return;c++;var $li=$('<li class="select2-results__option" role="option"></li>').text(label).attr('data-value',val);if(this.selected)$li.addClass('select2-results__option--selected').attr('aria-selected','true');$list.append($li);});if(!c)$list.append($('<li class="select2-results__message"></li>').text((opts.language&&opts.language.noResults?opts.language.noResults():'No results found')));}
$('body').append($drop);active=$drop;place($s,$box,$drop);render('');$box.addClass('select2-container--open');setTimeout(function(){$search.trigger('focus');},0);$search.on('input',function(){render(this.value);});$list.on('click','.select2-results__option',function(){var val=$(this).attr('data-value');$s.val(val).trigger('input').trigger('change');sync($s,$box);close();$box.removeClass('select2-container--open');});$(document).on('mousedown.novinfontSelect2',function(e){if(!$(e.target).closest($drop).length&&!$(e.target).closest($box).length){close();$box.removeClass('select2-container--open');}}).on('keydown.novinfontSelect2',function(e){if(e.key==='Escape'){close();$box.removeClass('select2-container--open');}});$(window).on('resize.novinfontSelect2 scroll.novinfontSelect2',function(){if(active)place($s,$box,$drop);});}
$.fn.select2=function(options){options=options||{};return this.each(function(){var $s=$(this);if($s.data('novinfont-select2')){sync($s,$s.data('novinfont-select2'));return;}var dir=options.dir||'ltr';var $box=$('<span class="select2 select2-container select2-container--novinfont" dir="'+dir+'"><span class="selection"><span class="select2-selection select2-selection--single" role="combobox" aria-haspopup="true" aria-expanded="false"><span class="select2-selection__rendered"></span><span class="select2-selection__arrow" aria-hidden="true"><b></b></span></span></span></span>');$s.addClass('select2-hidden-accessible').attr('aria-hidden','true').after($box);$s.data('novinfont-select2',$box);sync($s,$box);$box.on('click',function(e){e.preventDefault();open($s,$box,options);});$s.on('change.novinfontSelect2',function(){sync($s,$box);});});};
})(window.jQuery);
